/**
 * The sandbox engine: Anthropic's sandbox-runtime (`@anthropic-ai/sandbox-runtime`, pinned in package.json). Every
 * macOS Seatbelt profile and every Linux bubblewrap + seccomp invocation a fenced launch runs under is generated by
 * its own code, per launch, from a small static config (read denies with exact re-allows, write roots with denies
 * inside them, mach services, the run's proxy). Toolroll adds only what that config says (agent-fence.ts srtTermsOf),
 * plus, on macOS, a few static rules of its own appended to the profile (SEATBELT_TERMINALS for every launch,
 * SEATBELT_CHROMIUM for a project check's); the rest of the rules, their baseline and their limits are the runtime's.
 *
 * macOS: its profile builder runs in this process (it is synchronous), with this process's working folder set to the
 * launch's for the call, because the runtime anchors its mandatory write denies (.git/hooks, .vscode, shell profiles)
 * at the working folder. Linux: its builder is asynchronous, anchored at the working folder too, and leaves mount
 * points to clean up after the command, so each Linux launch runs through a small helper process
 * (sandbox-launch.ts) that changes into the launch's folder, asks the runtime for the command, runs it and cleans up.
 */
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { wrapCommandWithSandboxMacOS } from "@anthropic-ai/sandbox-runtime/dist/sandbox/macos-sandbox-utils.js";
import { checkLinuxDependencies, getLinuxDependencyStatus } from "@anthropic-ai/sandbox-runtime/dist/sandbox/linux-sandbox-utils.js";
import type { FsReadRestrictionConfig, FsWriteRestrictionConfig } from "@anthropic-ai/sandbox-runtime";

const require = createRequire(import.meta.url);

/** The engine and its exact version, as the console and the words say it. */
export const SANDBOX_RUNTIME: { name: string; version: string } = (() => {
  const name = "@anthropic-ai/sandbox-runtime";
  try {
    const manifest = JSON.parse(readFileSync(join(dirname(require.resolve(name)), "..", "package.json"), "utf8")) as { version?: unknown };
    return { name, version: typeof manifest.version === "string" ? manifest.version : "unknown" };
  } catch {
    return { name, version: "unknown" };
  }
})();

/** "Anthropic's sandbox-runtime 0.0.79": how every surface names the engine. */
export const sandboxRuntimeWords = (): string => `Anthropic's sandbox-runtime ${SANDBOX_RUNTIME.version}`;

/**
 * One launch's sandbox, as the runtime's own config: what it may not read (and the exact paths read again inside
 * those), where it may write (and what stays unwritable there), the extra macOS services it may look up, and its
 * network (open, or only through this run's proxy; a tool broker rides the runtime's second relay).
 */
export type SrtTerms = {
  readConfig: FsReadRestrictionConfig;
  writeConfig: FsWriteRestrictionConfig;
  allowMachLookup: string[];
  /** macOS: a project check's launch, whose Chromium may register and reach its own services (SEATBELT_CHROMIUM). */
  browser?: boolean;
  network: { kind: "open" } | { kind: "proxy"; httpPort: number; socksPort?: number; token?: string; localServices: boolean; unixSockets: string[] };
};

const SANDBOX_EXEC = "/usr/bin/sandbox-exec";
/** A deny-by-default profile, as the runtime's are: inside another sandbox one can't be applied (an allow-by-default one
 * still can, so it proves nothing). */
export const SEATBELT_PROBE = "(version 1)(deny default)(allow process-exec)(allow process-fork)(allow file-read*)(allow sysctl-read)(allow mach-lookup)";

/** Why the runtime can't sandbox here, or null when it can (checked before every launch; nothing runs bare). */
export function sandboxRuntimeProblem(platform: NodeJS.Platform = process.platform): string | null {
  if (platform === "darwin") {
    if (!existsSync(SANDBOX_EXEC)) return "this Mac has no sandbox-exec";
    const probe = spawnSync(SANDBOX_EXEC, ["-p", SEATBELT_PROBE, "/usr/bin/true"], { timeout: 5_000, stdio: "ignore" });
    return probe.status === 0 ? null : "sandbox-exec can't start a sandbox here (is this already inside one?)";
  }
  if (platform === "linux") {
    const checked = checkLinuxDependencies();
    if (checked.errors.length > 0) return checked.errors.join("; ");
    if (!getLinuxDependencyStatus().hasSeccompApply) return "the sandbox runtime's seccomp helper isn't available for this processor";
    // The runtime finds nested protected names (a subfolder's .git/hooks, .vscode, shell profiles) with ripgrep.
    if (spawnSync("rg", ["--version"], { timeout: 5_000, stdio: "ignore" }).status !== 0) return "ripgrep (rg) is not installed";
    const probe = spawnSync("bwrap", ["--ro-bind", "/", "/", "--unshare-pid", "--unshare-user", "--proc", "/proc", "--new-session", "--", "true"], { timeout: 5_000, stdio: "ignore" });
    return probe.status === 0 ? null : "bubblewrap can't start a sandbox here (unprivileged user namespaces may be off)";
  }
  return `the sandbox runtime has no sandbox for ${platform}`;
}

/** POSIX shell words. */
export function shellQuote(words: readonly string[]): string {
  return words.map(word => /^[A-Za-z0-9_@%+=:,./-]+$/.test(word) ? word : `'${word.replace(/'/g, `'\\''`)}'`).join(" ");
}

/**
 * The runtime sets a sandboxed command's TMPDIR itself (to $CLAUDE_CODE_TMPDIR of the process asking, or /tmp/claude):
 * the launch's own temp folder when it has one, so it keeps it; otherwise /tmp/claude, made if missing.
 */
export function withRuntimeTemp<T>(temp: string | undefined, make: () => T): T {
  const before = { code: process.env["CLAUDE_CODE_TMPDIR"], old: process.env["CLAUDE_TMPDIR"] };
  delete process.env["CLAUDE_TMPDIR"];
  if (temp !== undefined && temp !== "") process.env["CLAUDE_CODE_TMPDIR"] = temp;
  else { delete process.env["CLAUDE_CODE_TMPDIR"]; try { mkdirSync("/tmp/claude", { recursive: true, mode: 0o700 }); } catch { /* someone else's: writes there fail */ } }
  try { return make(); }
  finally {
    if (before.code === undefined) delete process.env["CLAUDE_CODE_TMPDIR"]; else process.env["CLAUDE_CODE_TMPDIR"] = before.code;
    if (before.old !== undefined) process.env["CLAUDE_TMPDIR"] = before.old;
  }
}

/**
 * Toolroll's own Seatbelt rules, appended to the end of the runtime's profile (Seatbelt takes the last rule that
 * matches). Static: constants here, never made from a launch's data.
 *
 * Terminals, every launch: a pseudo-terminal of its own (node-pty, `script`, a test that drives a shell), and no other.
 * The runtime's `allowPty` opens reads and writes on every /dev/ttys device, the operator's own open terminals among
 * them, and its baseline already reads them (a read steals what is typed there). macOS marks a terminal the sandboxed
 * process made with the `com.apple.sandbox.pty` extension, so only those are opened by name; the controlling terminal
 * (/dev/tty) and terminals handed down open stay as they were.
 */
export const SEATBELT_TERMINALS = [
  "; Toolroll: a pseudo-terminal the launch made itself, and no other terminal",
  "(allow pseudo-tty)",
  "(allow file-read* file-write* file-ioctl (literal \"/dev/ptmx\"))",
  "(allow file-read* file-write* file-ioctl (require-all (regex #\"^/dev/ttys[0-9]+$\") (extension \"com.apple.sandbox.pty\")))",
  "(deny file-read-data file-write* (require-all (regex #\"^/dev/ttys[0-9]+$\") (require-not (extension \"com.apple.sandbox.pty\"))))",
].join("\n");

/**
 * Chromium, a project check's launch only: Playwright's default browser (its Chromium headless shell) registers its
 * port rendezvous service as org.chromium.Chromium.MachPortRendezvousServer.<its pid> at start, and its helpers look
 * it up. Exactly that name. Chromium takes the prefix from its bundle id with no switch or variable to change it, and
 * Seatbelt can't tie the pid to the caller, so the residual (another pid's name registered or looked up) is written
 * up in SECURITY.md. Chrome for Testing (`channel: "chromium"`, headed runs) gets nothing: such a check runs Not
 * sandboxed.
 */
export const SEATBELT_CHROMIUM = [
  "; Toolroll: the Chromium headless shell port rendezvous service",
  "(allow mach-register mach-lookup (global-name-regex #\"^org\\.chromium\\.Chromium\\.MachPortRendezvousServer\\.[0-9]+$\"))",
].join("\n");

const PROFILE_OPENS = `${SANDBOX_EXEC} -p '`;

/**
 * `command` (the runtime's macOS invocation) with `rules` appended to its profile. The runtime quotes each word whole
 * in single quotes, a quote inside as '"'"'; the profile is the first word after `sandbox-exec -p` (only the runtime's
 * own environment words come before it). Anything else, and the launch is refused rather than run with less.
 */
export function withSeatbeltRules(command: string, rules: string): string {
  if (rules.includes("'")) throw new Error("a Seatbelt rule Toolroll adds can't hold a quote");
  const opens = command.indexOf(PROFILE_OPENS);
  if (opens < 0 || !command.startsWith("env ")) throw new Error("the sandbox runtime's command isn't the shape Toolroll knows");
  const start = opens + PROFILE_OPENS.length;
  let end = start;
  for (;;) {
    const quote = command.indexOf("'", end);
    if (quote < 0) throw new Error("the sandbox runtime's profile never ends");
    if (command.startsWith(`'"'"'`, quote)) { end = quote + 5; continue; }
    end = quote;
    break;
  }
  if (!command.startsWith("(version 1)\n(deny default", start) || !/^' \/\S+ -c /.test(command.slice(end))) throw new Error("the sandbox runtime's profile isn't the shape Toolroll knows");
  return `${command.slice(0, end)}\n${rules}\n${command.slice(end)}`;
}

/** The runtime's macOS invocation for `file args` run from `cwd`: a command line for /bin/sh. */
export function srtMacosCommand(file: string, args: readonly string[], terms: SrtTerms, cwd: string = process.cwd(), temp?: string): string {
  const network = terms.network;
  const params = {
    command: shellQuote([file, ...args]),
    needsNetworkRestriction: network.kind === "proxy",
    ...(network.kind === "proxy" ? {
      httpProxyPort: network.httpPort,
      ...(network.socksPort === undefined ? {} : { socksProxyPort: network.socksPort }),
      ...(network.token === undefined ? {} : { proxyAuthToken: network.token }),
      allowLocalBinding: network.localServices,
      ...(network.unixSockets.length === 0 ? {} : { allowUnixSockets: network.unixSockets }),
    } : {}),
    ...(terms.allowMachLookup.length === 0 ? {} : { allowMachLookup: terms.allowMachLookup }),
    readConfig: terms.readConfig,
    writeConfig: terms.writeConfig,
  };
  // The runtime anchors its mandatory write denies at this process's working folder: the launch's, for this call.
  const before = process.cwd();
  process.chdir(cwd);
  let command: string;
  try { command = withRuntimeTemp(temp, () => wrapCommandWithSandboxMacOS(params)); }
  finally { process.chdir(before); }
  return withSeatbeltRules(command, terms.browser === true ? `${SEATBELT_TERMINALS}\n${SEATBELT_CHROMIUM}` : SEATBELT_TERMINALS);
}

/** The Linux helper (sandbox-launch.ts) and the environment variable its launch is handed in. */
export const SANDBOX_LAUNCH_SPEC = "TOOLROLL_SANDBOX_LAUNCH";
export const sandboxLaunchHelper = (): string => {
  const beside = fileURLToPath(new URL("./sandbox-launch.js", import.meta.url));
  // Run from the sources (the test suite), the built helper is the package's own.
  return existsSync(beside) ? beside : fileURLToPath(new URL("../dist/sandbox-launch.js", import.meta.url));
};

/** What the Linux helper is given: the command, where it runs, and the terms. */
export type SandboxLaunchSpec = { file: string; args: string[]; cwd: string; terms: SrtTerms; temp?: string };

/**
 * `file args` inside the runtime's sandbox, as a spawn: on macOS `/bin/sh -c <its command>`; on Linux the helper,
 * handed the launch in its environment (never its arguments, which other users can list).
 */
export function srtSpawn(file: string, args: readonly string[], terms: SrtTerms, cwd: string = process.cwd(), temp?: string, platform: NodeJS.Platform = process.platform): { file: string; args: string[]; env: Record<string, string> } {
  if (platform === "darwin") {
    const command = srtMacosCommand(file, args, terms, cwd, temp);
    if (!command.includes(SANDBOX_EXEC)) throw new Error("the sandbox runtime returned the command unsandboxed");
    return { file: "/bin/sh", args: ["-c", command], env: {} };
  }
  const spec: SandboxLaunchSpec = { file, args: [...args], cwd, terms, ...(temp === undefined ? {} : { temp }) };
  return { file: process.execPath, args: [sandboxLaunchHelper()], env: { [SANDBOX_LAUNCH_SPEC]: JSON.stringify(spec) } };
}
